import pdfplumber
import pandas as pd
import json
import os

pdf_path = '/root/employees_backup.pdf'
excel_path = '/root/employees_current.xlsx'
output_path = '/root/diff_report.json'

def extract_pdf_data(path):
    all_data = []
    with pdfplumber.open(path) as pdf:
        for page in pdf.pages:
            tables = page.extract_tables()
            for table in tables:
                if table:
                    all_data.extend(table)

    if not all_data:
        return []

    # Assume first row is header
    header = all_data[0]
    data = all_data[1:]

    # Create list of dicts
    employees = []
    for row in data:
        # handle cases where row length might differ from header
        if len(row) != len(header):
            continue

        emp = {}
        for i, col in enumerate(header):
            val = row[i]
            # Try to convert to number if possible
            if val is not None:
                val = val.strip()
                try:
                    if '.' in val:
                        val = float(val)
                    else:
                        val = int(val)
                except ValueError:
                    pass # Keep as string
            emp[col.strip()] = val
        employees.append(emp)
    return employees

def extract_excel_data(path):
    df = pd.read_excel(path)
    return df.to_dict('records')

def normalize_data(data):
    # Ensure IDs are strings and keys are consistent
    normalized = {}
    for entry in data:
        # Find ID field - assuming it contains "ID" or "id"
        id_field = None
        for k in entry.keys():
            if 'ID' in k.upper():
                id_field = k
                break

        if not id_field:
            continue

        emp_id = str(entry[id_field])

        # Clean up keys and values
        clean_entry = {}
        for k, v in entry.items():
            key = k.strip()
            if key == id_field:
                continue # Skip ID in values for now, or keep it? Let's keep ID separately as key

            if pd.isna(v):
                v = None

            clean_entry[key] = v

        normalized[emp_id] = clean_entry
    return normalized

def main():
    print("Extracting PDF data...")
    pdf_data = extract_pdf_data(pdf_path)
    # print(f"PDF Sample: {pdf_data[:1]}")

    print("Extracting Excel data...")
    excel_data = extract_excel_data(excel_path)
    # print(f"Excel Sample: {excel_data[:1]}")

    old_employees = normalize_data(pdf_data)
    new_employees = normalize_data(excel_data)

    deleted_employees = []
    modified_employees = []

    # Find deleted
    for emp_id in old_employees:
        if emp_id not in new_employees:
            deleted_employees.append(emp_id)

    # Find modified
    for emp_id, old_data in old_employees.items():
        if emp_id in new_employees:
            new_data = new_employees[emp_id]

            for field, old_val in old_data.items():
                if field in new_data:
                    new_val = new_data[field]

                    # Normalize types for comparison
                    # Excel might have floats for integers, etc.

                    # Skip if both are None
                    if old_val is None and new_val is None:
                        continue

                    # If one is None and other is not
                    if (old_val is None) != (new_val is None):
                         modified_employees.append({
                            "id": emp_id,
                            "field": field,
                            "old_value": old_val,
                            "new_value": new_val
                        })
                         continue

                    # Compare values
                    # Handle numeric precision
                    is_diff = False
                    if isinstance(old_val, (int, float)) and isinstance(new_val, (int, float)):
                        if abs(old_val - new_val) > 0.001:
                            is_diff = True
                    else:
                        if str(old_val).strip() != str(new_val).strip():
                            is_diff = True

                    if is_diff:
                        # Normalize output types
                        # The prompt asks for:
                        # - numeric fields as numbers
                        # - text fields as strings

                        # Just use the raw values, but maybe ensure they look nice

                        modified_employees.append({
                            "id": emp_id,
                            "field": field,
                            "old_value": old_val,
                            "new_value": new_val
                        })

    # Sort results
    deleted_employees.sort()
    modified_employees.sort(key=lambda x: x['id'])

    result = {
        "deleted_employees": deleted_employees,
        "modified_employees": modified_employees
    }

    with open(output_path, 'w') as f:
        json.dump(result, f, indent=2)

    print(f"Report generated at {output_path}")

if __name__ == "__main__":
    main()

